ALTER TABLE plugin_webfilter_settings DROP COLUMN blockPageMessage;
ALTER TABLE plugin_webfilter_settings DROP COLUMN blockPageTitle;

changeSet.sql:
CREATE TABLE IF NOT EXISTS hwmdm_system_settings (
    key VARCHAR(100) PRIMARY KEY,
    value TEXT,
    updated TIMESTAMP DEFAULT now()
);
